    /// <summary>
    /// Get the localized string for HomePage_Welcome in es-ES (like '
    /// DateTime.Now.Hour switch
    /// {
    /// &gt;= 5 and &lt; 12 =&gt; &quot;Buenos días, &quot;,
    /// &gt;= 12 and &lt; 18 =&gt; &quot;Buenas tardes, &quot;,
    /// &gt;= 18 and &lt; 22 =&gt; &quot;Buenas tardes, &quot;,
    /// _ =&gt; &quot;Buenas noches, &quot;,
    /// } + WelcomeMessage
    /// ')
    /// </summary>
    /// <remarks>
    /// Expresión C# que devuelve un saludo basado en la hora del día, concatenado con &apos;WelcomeMessage&apos;. Se ajustaron los saludos al español (es-ES).
    /// </remarks>
    public string HomePage_Welcome() => DateTime.Now.Hour switch{>= 5 and < 12 => "Buenos días, ",>= 12 and < 18 => "Buenas tardes, ",>= 18 and < 22 => "Buenas tardes, ",_ => "Buenas noches, ",} + WelcomeMessage;
    
