    /// } + WelcomeMessage
    /// ')
    /// </summary>
    /// <remarks>
    /// Переведены приветствия по времени суток на русский язык. Сохранена структура C# switch выражения и конкатенация строк.
    /// </remarks>
    public string HomePage_Welcome() => DateTime.Now.Hour switch
{
    >= 5 and < 12 => "Доброе утро, ",
    >= 12 and < 18 => "Добрый день, ",
    >= 18 and < 22 => "Добрый вечер, ",
    _ => "Добрый вечер, ",
} + WelcomeMessage;
    
